export const ledger = {
  id: "ftrl-2025",
  title: "…论文标题…",
  subtitle: "29 claims extracted · grounded only against released code and data",
  source: { kind: "paper" | "live-research", ref: "arXiv:… 或 repo 路径" },
  root_hash: "sha256:7ef5…",
  counts: { settled: 9, open: 18, rejected: 2, dead_end: 0 },

  // 可选。页脚 provenance 行的文案（§9）。缺席时用 §9 默认文案。
  // 每个数据集应各自提供 —— 默认文案讲的是 RIT §7.4，挂在 My Research 上不准确。
  provenance: "Fixture data · … · no live verification performed",

  // 首屏要高亮的那一条（见 §6.1 callout）
  spotlight: { node_id: "c14", message: "This paper's headline number is OPEN." },

  nodes: [
    {
      id: "c07",
      label: "val_loss floor of 3.28 is reached within 3000 steps",   // 自然语言 @claim
      kind: "claim",            // claim|question|decision|experiment|dead_end|pivot
      status: "settled",        // settled|open|rejected|disputed
      tier: "L2",               // T0|T1|L1|L2|L3|K|null   (RIT Table 2)
      provenance: "ai-executed",// user|ai-suggested|ai-executed|user-revised (ARA P2)
      depends_on: ["c02"],

      // Hume's fork：一条 claim 劈成两半，走两个不同 oracle
      empirical: [{
        assertion: "val_loss <= 3.28",
        evidence_path: "evidence/data/train.log",
        sha256: "a41f9c…",
        extractor: { kind: "regex_float", pattern: "step:(\\d+)/M val_loss:([\\d.]+)", group: 2 },
        claimed: 3.28,
        extracted: 3.28,
        verdict: "pass"        // pass|fail|unreachable
      }],
      analytical: [{
        theorem: "reach_3025 : steps_to_target <= 3025",
        lean: "theorem reach_3025 : steps_to_target <= 3025 := by decide",
        verdict: "pass",        // pass|fail|unchecked
        axioms: ["Lean.trustCompiler", "cfg_grounding_b2"],
        whitelist_ok: true,
        has_sorry: false
      }],

      admission: {
        actor: "referee", actor_kind: "agent",   // human|agent
        at: "2026-05-11T09:22Z",
        why: "both oracles discharged; no collision with admitted set",
        supersedes: null
      },

      // 仅 status==="open" 时出现：为什么够不到
      unreachable: {
        reason: "The value is an average over training runs recorded in a wandb log the repository does not ship.",
        missing: ["wandb/run-*/summary.json"]
      },

      // 仅 kind==="dead_end" 时出现（ARA Table 1）
      dead_end: { hypothesis: "…", failure_mode: "…", lesson: "…" },

      // 仅 status==="disputed" 时出现（RIT Table 3）
      dispute: { with: "c11", kind: "A", proof: "theorem boom : False := …", resolution: "…" }
    }
  ]
};
```

